"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["75600"],{31684(e){e.exports=JSON.parse('{"id":"FIN-1471","slug":"out-of-court-restructuring","term":"Out-of-Court Restructuring","also_known_as":[],"difficulty":"Advanced","definition":"An out-of-court restructuring is a reorganisation of a company\'s debts and finances negotiated directly between the company and its creditors, without a formal court-supervised insolvency or bankruptcy process.","explanation":["When a company struggles to meet its debts, it can try to agree new terms with its lenders and bondholders privately. Options include extending maturities, reducing interest rates, swapping debt for equity, waiving covenant breaches or providing new financing.","For example, a company facing a loan repayment it cannot make might agree with its banks to extend the loan by three years, temporarily reduce interest and give the lenders a share of any future sale proceeds.","Out-of-court restructurings are usually faster, cheaper, more flexible and more private than formal proceedings. They avoid the stigma of bankruptcy and the disruption to customers, suppliers and employees.","Their main weakness is that they generally require agreement from all affected creditors, or a very high proportion, depending on the debt documents. A few holdout creditors can block a deal. In such cases, companies may use formal processes, such as Chapter 11 in the United States or restructuring plans in the United Kingdom, which can bind dissenting creditors."],"note":"","total":1725,"prev":{"slug":"other-comprehensive-income","term":"Other Comprehensive Income"},"next":{"slug":"out-of-pocket-maximum","term":"Out-of-Pocket Maximum"}}')}}]);